package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.*;
import org.springframework.transaction.support.TransactionTemplate;

/** Actual complete original day/registration/source/whole analysis/input/result/availability. External transports are fictional. */
class CatalogDayReportComponentTest {
    boolean mysql(){return false;}
    CatalogAnalysisReportCandidateTest helper(){return new CatalogAnalysisReportCandidateTest(){@Override boolean mysql(){return CatalogDayReportComponentTest.this.mysql();}};}
    <T>T read(CatalogPreviousAnalysisTest.Fixture f,java.util.function.Supplier<T> work){var tx=new TransactionTemplate(f.tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->work.get());}
    CatalogDayReportComponentService provider(CatalogDayAnalysisCompletionTest.Fixture f){var original=f.built().data().data().data().data();return new CatalogDayReportComponentService(original.outer().evidence(original.f(),f.clock()),original.f().graph.plans(),new CatalogVersionJudgmentLedger(new JdbcCatalogVersionJudgments(f.f().source),f.version().contentKind()),new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(f.f().source),f.version().contentKind()),f.service(),version->{var validity=f.built().data().validity().validity(CanonicalJson.parse(JdbcFrozenContentVersions.version(version)));return new CatalogDayReportComponentService.Validity(validity.effectiveValid(),false);},f.f().tx,f.version().contentKind());}
    @Test void FourActualCategoriesReturnEntireOriginalEntitySetWithExactBodyDependencyAndReference(){
        for(String category:List.of("agent","skill","workflow","model")){var f=helper().nativeCompletion(category,false);var service=provider(f.fixture());var component=service.capture(f.fixture().day(),f.cutoff());assertNotNull(component);assertEquals(category,component.category());assertEquals(f.fixture().day(),component.day());assertEquals(f.cutoff(),component.cutoff());assertEquals(1,component.candidates().size());assertEquals(f.completed().bodyJson(),component.candidates().getFirst().evidence().bodyJson());assertEquals(f.completed().version(),ContentVersionKey.fromJson(CanonicalJson.parse(component.referenceJson().getFirst())));assertEquals(f.completed().version().inputJobId(),component.dependencies().getFirst().id());assertTrue(component.missing().isEmpty());int jobs=f.fixture().f().jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);assertSame(component,read(f.fixture().f(),()->service.verifyObserved(component)));assertEquals(jobs,f.fixture().f().jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertThrows(UnsupportedOperationException.class,()->component.candidates().clear());assertFalse(component.toString().contains("fictional"));assertEquals(2,f.fixture().f().sends);}
    }
    @Test void AliasVersionTwoKeepsBothOriginalSourceMembersAndOneAnalysisCandidate(){var f=helper().nativeCompletion("agent",true);var component=provider(f.fixture()).capture(f.fixture().day(),f.cutoff());assertEquals(1,component.candidates().size());assertEquals(2,CanonicalJson.parse(component.candidates().getFirst().evidence().bodyJson()).get("citation_ids").size());assertEquals(1,component.dependencies().size());assertEquals(1,component.referenceJson().size());assertTrue(component.missing().isEmpty());}
    @Test void LateFirstObservationRemainsExplicitlyMissingAtOriginalCutoffAndCannotChangeThatComponent(){var h=helper().helper();var f=h.fixture("skill",false);var cutoff=f.day().plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant();var service=provider(f);var original=service.capture(f.day(),cutoff);assertEquals(1,original.candidates().size());assertNull(original.candidates().getFirst().evidence());assertEquals("not_completed_at_cutoff",original.candidates().getFirst().exclusionReason());assertEquals(1,original.missing().size());assertTrue(original.dependencies().isEmpty());h.observe(f,Clock.fixed(cutoff.plusSeconds(1),ZoneOffset.UTC));assertSame(original,read(f.f(),()->service.verifyObserved(original)));assertNull(service.capture(f.day(),cutoff).candidates().getFirst().evidence());assertNotNull(service.capture(f.day(),cutoff.plusSeconds(1)).candidates().getFirst().evidence());assertEquals(2,f.f().sends);}
    @Test void NewButUnallocatedEntityIsMissingAndOriginalDeclinedVersionIsExcludedWithoutCurrentHeader(){
        var outer=new CatalogDayAnalysisEligibilityTest(){@Override boolean mysql(){return CatalogDayReportComponentTest.this.mysql();}};
        var fresh=outer.new NewFixture();fresh.terminal("workflow");fresh.completeSource();var evidence=outer.evidence(fresh,Clock.fixed(outer.completed.plusSeconds(60),ZoneOffset.UTC));var day=evidence.capture(outer.day);assertNotNull(day);var source=fresh.f.source;var service=new CatalogDayReportComponentService(evidence,fresh.graph.plans(),new CatalogVersionJudgmentLedger(new JdbcCatalogVersionJudgments(source),"workflow"),new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(source),"workflow"),new CatalogDayAnalysisCompletionService(source,fresh.f.tx,fresh.f.clock,"workflow"),v->{throw new AssertionError("no completed analysis");},fresh.f.tx,"workflow");var cutoff=outer.day.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant();var missing=service.capture(outer.day,cutoff);assertEquals(1,missing.candidates().size());assertEquals("not_completed_at_cutoff",missing.candidates().getFirst().exclusionReason());assertEquals(1,missing.missing().size());assertTrue(missing.dependencies().isEmpty());
        var previous=outer.new Fixture();previous.terminal("workflow");var payload=CanonicalJson.parse(previous.raw).get("payload");((tools.jackson.databind.node.ObjectNode)payload.get("items").get(0)).put("reanalyze_recommended",false);previous.raw=ResultApplicationService.providerEnvelope(previous.application.input(),JdbcFrozenInputs.canonical(payload));previous.completeSource();var originals=outer.evidence(previous,Clock.fixed(outer.completed.plusSeconds(60),ZoneOffset.UTC));assertNotNull(originals.capture(outer.day));var originalSource=previous.f.source;var negative=new CatalogDayReportComponentService(originals,previous.graph.plans(),new CatalogVersionJudgmentLedger(new JdbcCatalogVersionJudgments(originalSource),"workflow"),new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(originalSource),"workflow"),new CatalogDayAnalysisCompletionService(originalSource,previous.f.tx,previous.f.clock,"workflow"),v->{throw new AssertionError("no new successful analysis");},previous.f.tx,"workflow");previous.f.jdbc.execute("DROP TABLE analyzed_entities");var excluded=negative.capture(outer.day,cutoff);assertEquals(1,excluded.candidates().size());assertFalse(excluded.candidates().getFirst().newOrReanalysisQualified());assertEquals("not_new_or_reanalysis",excluded.candidates().getFirst().exclusionReason());assertTrue(excluded.missing().isEmpty());assertTrue(excluded.referenceJson().isEmpty());
    }
    @Test void ActualUnknownVersionQualificationIsMissingRatherThanAnInventedNegative(){
        var outer=new CatalogDayAnalysisEligibilityTest(){@Override boolean mysql(){return CatalogDayReportComponentTest.this.mysql();}};var unknown=outer.new Fixture(){@Override void functional(String category,boolean unchanged,boolean missing,boolean recommend){super.functional(category,false,true,false);}};unknown.terminal("model");unknown.completeSource();var original=outer.evidence(unknown,Clock.fixed(outer.completed.plusSeconds(60),ZoneOffset.UTC));assertNotNull(original.capture(outer.day));var source=unknown.f.source;var service=new CatalogDayReportComponentService(original,unknown.graph.plans(),new CatalogVersionJudgmentLedger(new JdbcCatalogVersionJudgments(source),"model"),new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(source),"model"),new CatalogDayAnalysisCompletionService(source,unknown.f.tx,unknown.f.clock,"model"),v->{throw new AssertionError("unknown cannot complete analysis");},unknown.f.tx,"model");var component=service.capture(outer.day,outer.day.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant());assertEquals(1,component.candidates().size());assertNull(component.candidates().getFirst().evidence());assertEquals("analysis_qualification_unproven",component.candidates().getFirst().exclusionReason());assertEquals(1,component.missing().size());assertTrue(component.referenceJson().isEmpty());assertEquals(0,unknown.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_version_judgment'",Integer.class));
    }
    @Test void DamagedOriginalDayProofAndForeignIssuerOrWriterCannotAuthorizeComponent(){var f=helper().nativeCompletion("model",false);var service=provider(f.fixture());var component=service.capture(f.fixture().day(),f.cutoff());assertThrows(RuntimeException.class,()->service.verifyObserved(component));assertThrows(RuntimeException.class,()->read(f.fixture().f(),()->provider(f.fixture()).verifyObserved(component)));var writer=new TransactionTemplate(f.fixture().f().tx);writer.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);writer.execute(s->{assertThrows(RuntimeException.class,()->service.verifyObserved(component));assertThrows(RuntimeException.class,()->service.capture(f.fixture().day(),f.cutoff()));return null;});f.fixture().f().jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='source_day_dedup'",new byte[32]);assertThrows(RuntimeException.class,()->service.capture(f.fixture().day(),f.cutoff()));assertEquals(2,f.fixture().f().sends);}
    @Test void UnknownOriginalDayAndColdMandatoryPortsDoNotInventAnEmptyCompleteCategory(){var evidence=mock(CatalogDayEntityEvidenceService.class);var plans=mock(FrozenSourceStagePlanService.class);var judgments=mock(CatalogVersionJudgmentLedger.class);var reservations=mock(CatalogDayAnalysisReservationLedger.class);var completions=mock(CatalogDayAnalysisCompletionService.class);var eligibility=mock(CatalogDayReportComponentService.VersionEligibility.class);var tx=mock(PlatformTransactionManager.class);var service=new CatalogDayReportComponentService(evidence,plans,judgments,reservations,completions,eligibility,tx,"agent");verifyNoInteractions(evidence,plans,judgments,reservations,completions,eligibility,tx);assertNull(service.capture(LocalDate.of(2026,1,1),Instant.parse("2026-01-01T21:00:00Z")));verifyNoInteractions(plans,judgments,reservations,completions,eligibility,tx);assertThrows(RuntimeException.class,()->new CatalogDayReportComponentService(null,plans,judgments,reservations,completions,eligibility,tx,"agent"));}
}
